// H O S T
// set server name
function set_host(req, res) {
    var opts = {
        user: req.user,
        host: req.params[0],
        req: apiUtils.getRequestLogObject(req)
    }
    host = req.body.server;
    host = "0.0.0.0:1729"
    docker_host = "typedb:1729"
    create_client(host).then(async function (client) {
        let database_list = await client.databases.all();
        let db_names = []
        for (const db in database_list) {
            db_names.push(database_list[db]["_name"])
        }
        res.send(db_names);
    }).catch(function (err) {
        apiUtils.rejectHandler(req, res, err);
    })
};

function get_host(req, res) {
    res.send(host);
    return
};

// C L I E N T
async function create_client(host) {
    try {
        client = await TypeDB.coreClient(host);
        return client
    } catch (exception) {
        // notify node-red of client exception
        console.log("exception at creating client: ", exception)
        throw exception
    }
};

async function close_client() {
    await client.close();
    return
};

function get_client() {
    return client;
};

// D A T A B A S E
// list of all database
async function list_databases(req, res) {
    try {
        let dbs = []
        let databases = await client.databases.all()
        for (const index in databases) {
            dbs.push(databases[index]["_name"])
        };
        res.send(dbs);
        return
    } catch (exception) {
        return exception
    };
};

// connect to a database 
async function set_database(db) {
    try {
        database = db
        return
    } catch (exception) {
        console.log("Exception @set_database: ", exception)
        return exception
    };
};

//create database
async function create_database(database) {
    try {
        console.log("[DB] Creating database: ", database)
        await client.databases.create(database)
    } catch (exception) {
        console.log("Exception @create_database: ", exception)
        return exception
    };
};

//delete a database
async function delete_database(database) {
    console.log("Deleting database: ", database);
    try {
        await (await client.databases.get(database)).delete();
        console.log("[DB] Finished deleteing database");
    } catch (exception) {
        console.log("Excetpion @delete_database: ", exception);
        throw exception
    };
};

//S E S S I O N S
async function create_session(session_type) {
    try {
        console.log("Creating session to ", database, " of type  ", session_type);
        if (session_type === "DATA") {
            session = await client.session(database, SessionType.DATA);
        } else if (session_type === "SCHEMA") {
            session = await client.session(database, SessionType.SCHEMA);
        };
    } catch (exception) {
        console.log("Exception @ create_session: ", exception);
        return exception;
    };
};

async function close_session() {
    await session.close();
};

// T R A N S A C T I O N S
async function create_transaction(transaction_type) {
    try {
        console.log("Creating transaction to ", database, " of type  ", transaction_type);
        if (transaction_type === "READ") {
            transaction = await session.transaction(TransactionType.READ);
        } else if (transaction_type === "WRITE") {
            transaction = await session.transaction(TransactionType.WRITE);
        };
    } catch (exception) {
        console.log("Exception @create_transaciton: ", exception);
        return exception;
    };
};

async function close_transaction(transaction_type) {
    try {
        if (transaction_type === "READ") {
            await transaction.close();
        } else if (transaction_type === "WRITE") {
            console.log("\tcommitting transaction ... ")
            await transaction.commit();
            console.log("\tfinished committing transaction ")
        } else {
            throw "Please define if the closing transaction is READ or WRITE"
        };
    } catch (exception) {
        console.log(exception);
        throw exception;
    };
};

// K N O W L E D G E
async function knowledge(req, res) {
    console.log("INSIDE OF KNOWLEDGE");
    try {
        opts = req.body;
        console.log("opts ", opts);
        // if new schema and writing
        if (opts.session_type === "SCHEMA" && opts.transaction_type === "WRITE") {
            if (await client.databases.contains(opts.database)) {
                console.log("In if statement")
                await set_database(opts.database);
                await delete_database(opts.database);
                await create_database(opts.database);
                await create_session(opts.session_type);
                await create_transaction(opts.transaction_type);
                await database_schema(opts, res);
            } else {
                console.log("in else statement");
                await set_database(opts.database);
                await create_database(opts.database);
                await create_session("SCHEMA");
                await create_transaction("WRITE");
                await database_schema(opts, res);
            }
            res.send("Successfully added schema to database " + opts.database);
        };
    } catch (exception) {
        console.log("exception caught ", exception);
        console.log("exception message:", exception.message, typeof exception.message);
        res.status(500).send(exception.message);
    };
};

async function database_schema(opts, res) {
    try {
        await transaction.query.define(opts.schema);
        await close_transaction("WRITE");
        await session.close();
    } catch (exception) {
        throw exception;
    };
};

// C A U S A L
async function geminos_schema(opts, res) {
    const promise = new Promise(function (resolve, reject) {
        fs.readFile("./packages/node_modules/@node-red/editor-api/lib/admin/meta_model_schema.tql", "utf-8", async function (err, data, res) {
            if (err) reject(err)
            try {
                // defines causal meta model schema
                console.log("putting in schema to geminos model");
                console.log("data : ", data);
                await transaction.query.define(data);
                resolve("Added new causal model instance to database");
            } catch (exception) {
                console.log("caught exception b ", exception);
                throw exception;
            }
        })
    });
    await promise.then(async (value) => {
        console.log("Resolving ", value);
        await close_transaction("WRITE");
        await session.close();
        res.send(value);
    }).catch((err) => {
        console.log("Caught error");
    });
};

async function commit_section(gem_schema_key, type) {
    // create transaction
    if (type === "match") {
        this.typeql_schema_dict[gem_schema_key] = this.typeql_schema_dict[gem_schema_key].split("match");
        await this.typeql_schema_dict[gem_schema_key].forEach(async function (statement) {
            if (statement.length > 0) {
                statement = "match" + statement;
                await transaction.query.insert(statement);
            }
        });
    } else if (type === "insert") {
        this.typeql_schema_dict[gem_schema_key] = this.typeql_schema_dict[gem_schema_key].split(";");
        await this.typeql_schema_dict[gem_schema_key].forEach(async function (statement) {
            if (statement.length > 2) {
                statement += ";";
                await transaction.query.insert(statement);
            };
        });
    };
};

async function causal(req, res) {
    console.log("in causal deploy");
    try {
        opts = req.body;
        let res_message = "";
        if (await client.databases.contains(opts.database)) {
            res_message = "Cleared old model and ready for updates";
            await set_database(opts.database);
            await delete_database(opts.database);
            await create_database(opts.database);
            await create_session("SCHEMA");
            await create_transaction("WRITE");
            await geminos_schema(opts, res);
        } else {
            res_message = "Created new database";
            await set_database(opts.database);
            await create_database(opts.database);
            await create_session("SCHEMA");
            await create_transaction("WRITE");
            await geminos_schema(opts, res);
        }
    } catch (exception) {
        res.status(500).send(exception.message);
    }
}

